from datetime import datetime, timedelta, tzinfo


class ToyEastern(tzinfo):
    STD = timedelta(hours=-5)
    DST_START = datetime(2024, 3, 10, 2, 0)
    DST_END = datetime(2024, 11, 3, 1, 0)

    def dst(self, dt):
        naive = dt.replace(tzinfo=None)
        if self.DST_START <= naive < self.DST_END:
            return timedelta(hours=1)
        return timedelta(0)

    def utcoffset(self, dt):
        return self.STD + self.dst(dt)

    def tzname(self, dt):
