def download_report(session: requests.Session, url: str) -> tuple[bytes, float]:
    started = time.monotonic()
    chunks, size = [], 0
    with session.get(url, stream=True, timeout=(3.05, 10)) as resp:
        resp.raise_for_status()
        for chunk in resp.iter_content(chunk_size=65536):
            if time.monotonic() - started > DEADLINE_SECONDS:
                raise TimeoutError(f"{url} exceeded {DEADLINE_SECONDS}s")
            size += len(chunk)
            if size > MAX_BYTES:
                raise ValueError(f"{url} exceeded {MAX_BYTES} bytes")
            chunks.append(chunk)
    return b"".join(chunks), time.monotonic() - started

